_CORE_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: 3.0 * (trucks not on own base) + 1.5 * (scooters not on own base).\n# Moves precede service; stock then regenerates and is rounded to 2 decimals.\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nTYPES = {"truck": (8, 3.0, 1), "scooter": (3, 1.5, 2)}\n\n\ndef payout(own, opponent, stock):\n    denominator = max(own + opponent, stock)\n    if denominator <= 0:\n        return 0.0\n    return own * stock / denominator\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.dist = None\n        self.targets = {}\n        self.bad_reports = 0\n        self.conservative = False\n\n    def _build_map(self, obs):\n        n = int(obs["n_nodes"])\n        adj = [[] for _ in range(n)]\n        for u, v in obs.get("edges", []):\n            adj[u].append(v)\n            adj[v].append(u)\n        for neighbors in adj:\n            neighbors.sort()\n        dist = []\n        for source in range(n):\n            row = [n + 1] * n\n            row[source] = 0\n            queue = deque([source])\n            while queue:\n                u = queue.popleft()\n                for v in adj[u]:\n                    if row[v] == n + 1:\n                        row[v] = row[u] + 1\n                        queue.append(v)\n            dist.append(row)\n        self.dist = dist\n        self.adj = adj\n        self.n = n\n\n    def _node_forecast(self, node, capacities, enemy, stock, maximum,\n                       regen, discounts):\n        """Exact stationary-opponent stock evolution for an existing plan."""\n        value = 0.0\n        states = []\n        for t, own in enumerate(capacities):\n            states.append(stock)\n            value += discounts[t] * (\n                payout(own, enemy, stock) - payout(enemy, own, stock)\n            )\n            stock = round(min(maximum, max(0.0, stock - min(\n                stock, own + enemy)) + regen), 2)\n        return value, states\n\n    def _candidate(self, uid, target, units, schedules, enemies, obs,\n                   horizon, discounts, baseline):\n        kind, source = units[uid]\n        capacity, cost, speed = TYPES[kind]\n        base = int(obs["player_base"])\n        distance = self.dist[source][target]\n        arrival = max(0, (distance + speed - 1) // speed - 1)\n        if arrival >= horizon:\n            return -1e20, 0, arrival\n\n        turns_left = max(0, N_TURNS - int(obs.get("turn", 0)))\n        return_travel = max(\n            0, (self.dist[target][base] + speed - 1) // speed - 1\n        )\n        stock_now = float(obs["stock"][target])\n        maximum = float(obs["stock_max"][target])\n        regen = float(obs["regen"][target])\n        enemy = enemies[target]\n        schedule = schedules[target]\n        best = -1e20\n        best_duration = 0\n\n        # The candidate serves for a finite burst, then can return home.\n        # Testing durations avoids treating renewable stock as static demand.\n        travel_cost = cost * sum(discounts[:arrival])\n        for duration in range(1, horizon - arrival + 1):\n            end = arrival + duration\n            stock = stock_now\n            value = 0.0\n            for t in range(horizon):\n                own = schedule[t]\n                if arrival <= t < end:\n                    own += capacity\n                value += discounts[t] * (\n                    payout(own, enemy, stock) - payout(enemy, own, stock)\n                )\n                stock = round(min(maximum, max(\n                    0.0, stock - min(stock, own + enemy)\n                ) + regen), 2)\n\n            operating_cost = cost * sum(discounts[arrival:end])\n            # Returning onto home is free. Only intermediate return turns cost.\n            charged_return = min(return_travel, max(0, turns_left - end))\n            return_cost = sum(\n                cost * (0.95 ** (end + k)) for k in range(charged_return)\n            )\n            gain = value - baseline[target] - travel_cost\n            gain -= operating_cost + return_cost\n            if gain > best:\n                best = gain\n                best_duration = duration\n\n        # Small hysteresis only for genuinely unfinished trips.\n        old_target = self.targets.get(uid)\n        if target == old_target and source != target and best > 0:\n            best += 0.35\n        return best, best_duration, arrival\n\n    def _plan(self, obs, deadline):\n        units = obs.get("player_units", {})\n        base = int(obs["player_base"])\n        plan = {uid: base for uid in sorted(units)}\n        remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n        if not units or remaining == 0:\n            return plan\n        horizon = min(8, remaining)\n        discounts = [0.95 ** t for t in range(horizon)]\n        schedules = [[0] * horizon for _ in range(self.n)]\n        enemies = [0] * self.n\n        for kind, node in obs.get("opponent_units", {}).values():\n            if kind in TYPES and 0 <= node < self.n:\n                enemies[node] += TYPES[kind][0]\n\n        nodes = [\n            v for v in range(self.n)\n            if float(obs["stock_max"][v]) > 0.0\n        ]\n        baseline = [0.0] * self.n\n        versions = [0] * self.n\n\n        def update_baseline(v):\n            baseline[v] = self._node_forecast(\n                v, schedules[v], enemies[v], float(obs["stock"][v]),\n                float(obs["stock_max"][v]), float(obs["regen"][v]),\n                discounts\n            )[0]\n\n        for v in nodes:\n            update_baseline(v)\n\n        heap = []\n        for uid in sorted(units):\n            if time.perf_counter() >= deadline:\n                break\n            if units[uid][0] not in TYPES:\n                continue\n            for v in nodes:\n                gain, duration, arrival = self._candidate(\n                    uid, v, units, schedules, enemies, obs,\n                    horizon, discounts, baseline\n                )\n                heapq.heappush(\n                    heap, (-gain, uid, v, versions[v], duration, arrival)\n                )\n\n        assigned = set()\n        while heap and time.perf_counter() < deadline:\n            negative_gain, uid, v, version, duration, arrival = heapq.heappop(heap)\n            if uid in assigned:\n                continue\n            if version != versions[v]:\n                gain, duration, arrival = self._candidate(\n                    uid, v, units, schedules, enemies, obs,\n                    horizon, discounts, baseline\n                )\n                heapq.heappush(\n                    heap, (-gain, uid, v, versions[v], duration, arrival)\n                )\n                continue\n            # A margin above zero protects against numerical noise and\n            # the conservative approximation of service during travel.\n            if -negative_gain <= 0.10:\n                break\n            assigned.add(uid)\n            plan[uid] = v\n            capacity = TYPES[units[uid][0]][0]\n            for t in range(arrival, arrival + duration):\n                schedules[v][t] += capacity\n            versions[v] += 1\n            update_baseline(v)\n        return plan\n\n    def _legal_action(self, obs, plan):\n        moves = {}\n        for uid in sorted(obs.get("player_units", {})):\n            kind, source = obs["player_units"][uid]\n            if kind not in TYPES:\n                continue\n            speed = TYPES[kind][2]\n            target = plan.get(uid, int(obs["player_base"]))\n            if not isinstance(target, int) or not 0 <= target < self.n:\n                continue\n            if source == target:\n                continue\n            # Closest-first transport of each individually identified unit.\n            # Among shortest-path steps, prefer immediate available stock.\n            reachable = [\n                v for v in range(self.n)\n                if self.dist[source][v] <= speed\n                and self.dist[v][target] < self.dist[source][target]\n            ]\n            if not reachable:\n                continue\n            destination = min(\n                reachable,\n                key=lambda v: (\n                    self.dist[v][target],\n                    -float(obs["stock"][v]),\n                    v,\n                ),\n            )\n            if (uid in obs["player_units"] and\n                    0 <= destination < self.n and\n                    self.dist[source][destination] <= speed):\n                moves[str(uid)] = int(destination)\n        return {"moves": moves}\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * float(TIME_BUDGET))\n        if self.dist is None or self.n != int(obs["n_nodes"]):\n            self._build_map(obs)\n        if (obs.get("n_invalid_actions_last_turn", 0) or\n                not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n            if self.bad_reports >= 2:\n                self.conservative = True\n\n        # Homeward fallback is legal and avoids stranding idle couriers.\n        fallback = {\n            uid: int(obs["player_base"])\n            for uid in obs.get("player_units", {})\n        }\n        if time.perf_counter() >= deadline:\n            return self._legal_action(obs, fallback)\n        plan = self._plan(obs, deadline)\n        action = self._legal_action(obs, plan)\n        self.targets = dict(plan)\n        return action\n'
