_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Running cost: 3.0 per truck and 1.5 per scooter not on its own base;\n# couriers on their own base cost nothing and serve nothing.\n#\n# Conservative policy: harvest only nodes within one move of home. Every\n# normal deployment earns a clearly positive immediate profit and can return\n# home next turn for free. No speculative travel, multi-turn commitments,\n# contested-node entries, or multiple friendly couriers at a harvest node.\n\nfrom collections import deque\nimport time\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\nMIN_PROFIT = 0.75\n\n\ndef served(capacity, opponent_capacity, stock):\n    """The specification\'s payout, including the zero-denominator case."""\n    denominator = max(capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return capacity * stock / denominator\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [n + 1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] == n + 1:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n    return distances\n\n\ndef retreat_destination(position, home, speed, distances):\n    """Take the largest possible safe step toward home."""\n    candidates = [\n        node for node in range(len(distances))\n        if distances[position][node] <= speed\n    ]\n    if not candidates:\n        return position\n    return min(candidates, key=lambda node: (distances[node][home], node))\n\n\ndef make_plan(obs, distances, deadline):\n    units = obs.get("player_units", {})\n    n = len(distances)\n    home = int(obs["player_base"])\n    stock = obs.get("stock", [])\n    opponent_capacity = [0] * n\n    for kind, position in obs.get("opponent_units", {}).values():\n        if kind in UNIT_TYPES and 0 <= position < n:\n            opponent_capacity[position] += UNIT_TYPES[kind][0]\n\n    # Returning home is the default. This also works when first called in the\n    # middle of a match with units in positions this policy would never choose.\n    plan = {}\n    for uid in sorted(units):\n        kind, position = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        speed = UNIT_TYPES[kind][2]\n        plan[uid] = retreat_destination(position, home, speed, distances)\n\n    if not 0 <= int(obs.get("turn", 0)) < N_TURNS:\n        return plan\n\n    # Returning units from arbitrary outside positions may have to stop away\n    # from home. Do not send another courier onto those reserved nodes.\n    reserved = {\n        destination for destination in plan.values()\n        if destination != home\n    }\n\n    # Nearest nodes first; at each node prefer the courier with the largest\n    # immediate net revenue. Trucks efficiently harvest full stocks; scooters\n    # take smaller stocks and maintain profitable regeneration streams.\n    nodes = sorted(\n        (node for node in range(n)\n         if node != home and node < len(stock) and stock[node] > 0),\n        key=lambda node: (distances[home][node], node),\n    )\n    assigned = set()\n    for node in nodes:\n        if time.perf_counter() >= deadline:\n            break\n        if node in reserved or opponent_capacity[node] > 0:\n            continue\n\n        best = None\n        for uid in sorted(units):\n            if uid in assigned:\n                continue\n            kind, position = units[uid]\n            if kind not in UNIT_TYPES or not 0 <= position < n:\n                continue\n            capacity, cost, speed = UNIT_TYPES[kind]\n\n            # Both the outbound move now and a free return home next turn\n            # must be possible. There are no unpaid transit turns.\n            if distances[home][node] > speed:\n                continue\n            if distances[position][node] > speed:\n                continue\n\n            revenue = served(capacity, opponent_capacity[node], float(stock[node]))\n            profit = revenue - cost\n            if profit < MIN_PROFIT:\n                continue\n\n            candidate = (\n                -profit,\n                distances[position][node],\n                0 if position == node else 1,\n                uid,\n            )\n            if best is None or candidate < best:\n                best = candidate\n\n        if best is not None:\n            uid = best[-1]\n            plan[uid] = node\n            assigned.add(uid)\n            reserved.add(node)\n\n    return plan\n\n\ndef legal_action(plan, units, distances):\n    """Validate every move using only the start-of-turn positions."""\n    moves = {}\n    n = len(distances)\n    for uid in sorted(plan):\n        if uid not in units or not isinstance(uid, str):\n            continue\n        kind, position = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        destination = int(plan[uid])\n        if not 0 <= destination < n:\n            continue\n        if distances[position][destination] > UNIT_TYPES[kind][2]:\n            continue\n        if destination != position:\n            moves[str(uid)] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.distances = None\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if key != self.map_key:\n            self.distances = preprocess_map(n, edges)\n            self.map_key = key\n\n        home = int(obs.get("player_base", -1))\n        if not 0 <= home < n:\n            return {"moves": {}}\n\n        plan = make_plan(obs, self.distances, deadline)\n        return legal_action(\n            plan, obs.get("player_units", {}), self.distances\n        )\n'
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
